sed -i '/\/\/ 4. Interactive Proximity Radar Blips/i \                    val isLoading = isInitialLoad || isRefreshing\n\n                    if (isLoading && isLocationEnabled) {\n                        for (i in 0..4) {\n                            val angleRad = Math.toRadians((i * 72.0) - 90.0 + (sweepAngle / 2))\n                            val distanceFraction = 0.4 + (i * 0.1)\n                            val radiusPx = (112.dp.value * distanceFraction).toFloat()\n                            val xOffsetDp = (radiusPx * cos(angleRad)).toInt().dp\n                            val yOffsetDp = (radiusPx * sin(angleRad)).toInt().dp\n\n                            val alphaPulse = (sin(sweepAngle * Math.PI / 180 + i) / 2 + 0.5).toFloat()\n                            Box(\n                                modifier = Modifier\n                                    .offset(x = xOffsetDp, y = yOffsetDp)\n                                    .size(28.dp)\n                                    .clip(CircleShape)\n                                    .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = alphaPulse * 0.6f + 0.2f))\n                            )\n                        }\n                    } else' app/src/main/java/com/example/ui/components/LiveRadarComponent.kt
